  INSERT INTO `MEDICATION` (`MedicationID`, `MedicationName`, `Description`) VALUES
  (6000001, 'Demo-MC26: Paracetamol 500mg', 'Thuốc giảm đau, hạ sốt cơ bản.'),
  (6000002, 'Demo-MC26: Amoxicillin 250mg', 'Kháng sinh điều trị nhiễm khuẩn.'),
  (6000003, 'Demo-MC26: Loratadine 10mg', 'Thuốc chống dị ứng thế hệ mới.'),
  (6000004, 'Demo-MC26: Omeprazole 20mg', 'Điều trị trào ngược dạ dày, viêm loét.'),
  (6000005, 'Demo-MC26: Metformin 500mg', 'Kiểm soát đường huyết cho tiểu đường type 2.'),
  (6000006, 'Demo-MC26: Amlodipine 5mg', 'Thuốc hạ huyết áp.'),
  (6000007, 'Demo-MC26: Ibuprofen 400mg', 'Kháng viêm không steroid (NSAID).'),
  (6000008, 'Demo-MC26: Vitamin C 1000mg', 'Bổ sung vitamin, tăng cường đề kháng.'),
  (6000009, 'Demo-MC26: Cetirizine 10mg', 'Thuốc trị viêm mũi dị ứng.'),
  (6000010, 'Demo-MC26: Azithromycin 500mg', 'Kháng sinh phổ rộng mạnh.'),
  (6000011, 'Demo-MC26: Pantoprazole 40mg', 'Ức chế bơm proton, bảo vệ dạ dày.'),
  (6000012, 'Demo-MC26: Losartan 50mg', 'Điều trị tăng huyết áp và suy tim.'),
  (6000013, 'Demo-MC26: Salbutamol 100mcg', 'Thuốc cắt cơn hen suyễn dạng xịt.'),
  (6000014, 'Demo-MC26: Aspirin 81mg', 'Ngừa huyết khối tĩnh mạch, bảo vệ tim mạch.'),
  (6000015, 'Demo-MC26: Atorvastatin 20mg', 'Điều trị mỡ máu cao, giảm cholesterol.'),
  (6000016, 'Demo-MC26: Naproxen 250mg', 'Thuốc chống viêm không steroid, dùng giảm đau và viêm; cần lưu ý nguy cơ kích ứng và xuất huyết tiêu hóa.'),
  (6000017, 'Demo-MC26: Diclofenac 50mg', 'Thuốc kháng viêm không steroid, hỗ trợ giảm đau cơ xương khớp.'),
  (6000018, 'Demo-MC26: Celecoxib 200mg', 'Thuốc kháng viêm chọn lọc COX-2, dùng trong một số tình trạng đau viêm.'),
  (6000019, 'Demo-MC26: Meloxicam 7.5mg', 'Thuốc kháng viêm giảm đau nhóm NSAID.'),
  (6000020, 'Demo-MC26: Tramadol 50mg', 'Thuốc giảm đau opioid, chỉ dùng theo chỉ định và theo dõi y tế.'),
  (6000021, 'Demo-MC26: Codeine 15mg', 'Thuốc giảm đau opioid, cần tuân thủ chặt chẽ chỉ định của bác sĩ.'),
  (6000022, 'Demo-MC26: Dextromethorphan 15mg', 'Thuốc giảm ho tác động trung ương.'),
  (6000023, 'Demo-MC26: Guaifenesin 100mg', 'Thuốc long đờm, hỗ trợ làm loãng dịch tiết đường hô hấp.'),
  (6000024, 'Demo-MC26: Acetylcysteine 200mg', 'Thuốc tiêu nhầy, hỗ trợ làm loãng đờm.'),
  (6000025, 'Demo-MC26: Ambroxol 30mg', 'Thuốc long đờm, hỗ trợ vận chuyển chất nhầy đường hô hấp.'),
  (6000026, 'Demo-MC26: Bromhexine 8mg', 'Thuốc tiêu nhầy, hỗ trợ giảm độ quánh của đờm.'),
  (6000027, 'Demo-MC26: Montelukast 10mg', 'Thuốc đối kháng thụ thể leukotriene, dùng trong một số trường hợp hen và viêm mũi dị ứng.'),
  (6000028, 'Demo-MC26: Budesonide inhaler 200mcg', 'Corticosteroid dạng hít giúp kiểm soát viêm đường hô hấp theo chỉ định.'),
  (6000029, 'Demo-MC26: Fluticasone nasal spray 50mcg', 'Corticosteroid xịt mũi dùng kiểm soát triệu chứng viêm mũi dị ứng.'),
  (6000030, 'Demo-MC26: Fexofenadine 180mg', 'Thuốc kháng histamine giảm triệu chứng dị ứng.'),
  (6000031, 'Demo-MC26: Desloratadine 5mg', 'Thuốc kháng histamine dùng giảm hắt hơi, ngứa và chảy mũi do dị ứng.'),
  (6000032, 'Demo-MC26: Chlorpheniramine 4mg', 'Thuốc kháng histamine thế hệ cũ; có thể gây buồn ngủ.'),
  (6000033, 'Demo-MC26: Hydrocortisone cream 1%', 'Corticosteroid bôi ngoài da nhẹ, dùng ngắn hạn theo hướng dẫn chuyên môn.'),
  (6000034, 'Demo-MC26: Clotrimazole cream 1%', 'Thuốc kháng nấm dùng ngoài da.'),
  (6000035, 'Demo-MC26: Miconazole cream 2%', 'Thuốc kháng nấm dùng điều trị một số nhiễm nấm da.'),
  (6000036, 'Demo-MC26: Terbinafine cream 1%', 'Thuốc kháng nấm dùng ngoài da.'),
  (6000037, 'Demo-MC26: Mupirocin ointment 2%', 'Kháng sinh bôi ngoài da cho một số nhiễm khuẩn da theo chỉ định.'),
  (6000038, 'Demo-MC26: Fusidic acid cream 2%', 'Kháng sinh dùng ngoài da cho một số nhiễm khuẩn da.'),
  (6000039, 'Demo-MC26: Benzoyl peroxide gel 5%', 'Hoạt chất bôi hỗ trợ điều trị mụn trứng cá.'),
  (6000040, 'Demo-MC26: Adapalene gel 0.1%', 'Retinoid bôi dùng trong điều trị mụn trứng cá.'),
  (6000041, 'Demo-MC26: Doxycycline 100mg', 'Kháng sinh nhóm tetracycline, dùng cho một số nhiễm khuẩn theo chỉ định.'),
  (6000042, 'Demo-MC26: Cephalexin 500mg', 'Kháng sinh cephalosporin dùng điều trị một số nhiễm khuẩn.'),
  (6000043, 'Demo-MC26: Cefuroxime 250mg', 'Kháng sinh cephalosporin dùng trong một số nhiễm khuẩn.'),
  (6000044, 'Demo-MC26: Cefixime 200mg', 'Kháng sinh cephalosporin dùng theo đánh giá của bác sĩ.'),
  (6000045, 'Demo-MC26: Ciprofloxacin 500mg', 'Kháng sinh fluoroquinolone dành cho một số nhiễm khuẩn; có các cảnh báo an toàn quan trọng.'),
  (6000046, 'Demo-MC26: Levofloxacin 500mg', 'Kháng sinh fluoroquinolone dùng cho một số nhiễm khuẩn theo chỉ định.'),
  (6000047, 'Demo-MC26: Clarithromycin 500mg', 'Kháng sinh macrolide dùng điều trị một số nhiễm khuẩn.'),
  (6000048, 'Demo-MC26: Clindamycin 300mg', 'Kháng sinh dùng cho một số nhiễm khuẩn do vi khuẩn nhạy cảm.'),
  (6000049, 'Demo-MC26: Nitrofurantoin 100mg', 'Kháng sinh dùng trong một số trường hợp nhiễm khuẩn đường tiết niệu.'),
  (6000050, 'Demo-MC26: Fluconazole 150mg', 'Thuốc kháng nấm dùng cho một số bệnh nhiễm nấm.'),
  (6000051, 'Demo-MC26: Acyclovir 400mg', 'Thuốc kháng virus dùng trong một số bệnh do herpes.'),
  (6000052, 'Demo-MC26: Valacyclovir 500mg', 'Thuốc kháng virus dùng điều trị một số nhiễm virus herpes.'),
  (6000053, 'Demo-MC26: Oseltamivir 75mg', 'Thuốc kháng virus cúm, hiệu quả phụ thuộc thời điểm và chỉ định sử dụng.'),
  (6000054, 'Demo-MC26: Oral rehydration salts', 'Dung dịch bù nước và điện giải đường uống khi mất nước nhẹ đến vừa.'),
  (6000055, 'Demo-MC26: Zinc sulfate 20mg', 'Bổ sung kẽm trong trường hợp cần thiết theo hướng dẫn y tế.'),
  (6000056, 'Demo-MC26: Ferrous sulfate 325mg', 'Chế phẩm bổ sung sắt dùng trong điều trị hoặc dự phòng thiếu sắt.'),
  (6000057, 'Demo-MC26: Folic acid 1mg', 'Bổ sung acid folic khi có chỉ định.'),
  (6000058, 'Demo-MC26: Vitamin D3 1000IU', 'Bổ sung vitamin D khi cần thiết.'),
  (6000059, 'Demo-MC26: Calcium carbonate 500mg', 'Bổ sung calci khi khẩu phần hoặc nhu cầu cần được hỗ trợ.'),
  (6000060, 'Demo-MC26: Vitamin B complex', 'Chế phẩm bổ sung các vitamin nhóm B.'),
  (6000061, 'Demo-MC26: Magnesium oxide 250mg', 'Chế phẩm bổ sung magnesi trong một số trường hợp.'),
  (6000062, 'Demo-MC26: Levothyroxine 50mcg', 'Hormone tuyến giáp tổng hợp dùng điều trị suy giáp theo theo dõi xét nghiệm.'),
  (6000063, 'Demo-MC26: Propylthiouracil 50mg', 'Thuốc kháng giáp dùng trong một số trường hợp cường giáp dưới giám sát chuyên khoa.'),
  (6000064, 'Demo-MC26: Gliclazide 30mg MR', 'Thuốc hạ đường huyết nhóm sulfonylurea, có nguy cơ hạ đường huyết.'),
  (6000065, 'Demo-MC26: Sitagliptin 100mg', 'Thuốc hỗ trợ kiểm soát đường huyết ở người đái tháo đường type 2.'),
  (6000066, 'Demo-MC26: Empagliflozin 10mg', 'Thuốc ức chế SGLT2 dùng trong một số trường hợp đái tháo đường type 2.'),
  (6000067, 'Demo-MC26: Insulin glargine 100U/mL', 'Insulin tác dụng kéo dài; liều dùng cần cá thể hóa và theo dõi đường huyết.'),
  (6000068, 'Demo-MC26: Glimepiride 2mg', 'Thuốc hạ đường huyết nhóm sulfonylurea, cần theo dõi nguy cơ hạ đường huyết.'),
  (6000069, 'Demo-MC26: Lisinopril 10mg', 'Thuốc ức chế men chuyển dùng điều trị tăng huyết áp và một số bệnh tim mạch.'),
  (6000070, 'Demo-MC26: Enalapril 5mg', 'Thuốc ức chế men chuyển dùng trong tăng huyết áp và một số bệnh tim.'),
  (6000071, 'Demo-MC26: Valsartan 80mg', 'Thuốc chẹn thụ thể angiotensin II dùng điều trị tăng huyết áp.'),
  (6000072, 'Demo-MC26: Bisoprolol 2.5mg', 'Thuốc chẹn beta dùng trong một số bệnh tim mạch theo chỉ định.'),
  (6000073, 'Demo-MC26: Carvedilol 6.25mg', 'Thuốc chẹn beta và alpha dùng trong một số bệnh tim mạch.'),
  (6000074, 'Demo-MC26: Hydrochlorothiazide 25mg', 'Thuốc lợi tiểu thiazide dùng điều trị tăng huyết áp và phù.'),
  (6000075, 'Demo-MC26: Furosemide 40mg', 'Thuốc lợi tiểu quai dùng trong một số tình trạng phù.'),
