-- =============================================================
-- MEDICONNECT PHASE 3 -> PHASE 4
-- Huy + Dang corrected integrated mock data
-- 11,101 NEW rows; keeps all existing Phrase3 rows unchanged.
-- High ID namespace 6,000,000+, usernames mc26_*, licenses MC26-*
-- Note: never re-run successfully imported file.
-- Do NOT disable FK checks or triggers.
-- Requirement: MySQL 8.x + privilege CREATE ROUTINE for current user.
-- FIRST back up Phrase3 and run MC26_00_PRECHECK.sql.
-- This procedure wraps the imports in a transaction and ROLLBACKS on error.
-- =============================================================
USE `Phrase3`;
DELIMITER $$
DROP PROCEDURE IF EXISTS `mc26_import_once`$$
CREATE PROCEDURE `mc26_import_once`()
BEGIN
  DECLARE conflict_count INT DEFAULT 0;
  DECLARE inserted_count INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;
  START TRANSACTION;
  SELECT COUNT(*) INTO conflict_count FROM `USER_ACCOUNT` WHERE `UserID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `SPECIALTY` WHERE `SpecialtyID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `DOCTOR` WHERE `DoctorID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `PATIENT` WHERE `Patient` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `GENERAL_PRACTITIONED` WHERE `DoctorID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `SPECIALIST` WHERE `DoctorID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `DOCTOR_SCHEDULE` WHERE `ScheduleID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `MEDICATION` WHERE `MedicationID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `APPOINTMENT` WHERE `AppointmentID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `CONSULTATION_SESSION` WHERE `SessionID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `MEDICAL_HISTORY` WHERE `MedicalHistoryID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `PRESCRIPTION` WHERE `PrescriptionID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM `PRESCRIPTION_ITEM` WHERE `PrescriptionItemID` BETWEEN 6000000 AND 6099999;
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: existing reserved IDs. Stop.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM USER_ACCOUNT WHERE LEFT(Username,5)='mc26_';
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: username prefix conflict.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM DOCTOR WHERE LEFT(LicenseNumber,5)='MC26-';
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: license prefix conflict.'; END IF;
  SELECT COUNT(*) INTO conflict_count FROM MEDICATION WHERE LEFT(MedicationName,11)='Demo-MC26: ';
  IF conflict_count > 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'MC26 import: medication prefix conflict.'; END IF;

  -- USER_ACCOUNT: 1,062 new rows (originals remapped to reserved ID range).

  -- SPECIALTY: 15 new rows (originals remapped to reserved ID range).

  -- DOCTOR: 88 new rows (originals remapped to reserved ID range).

  -- PATIENT: 974 new rows (originals remapped to reserved ID range).

  -- GENERAL_PRACTITIONED: 36 new rows (originals remapped to reserved ID range).

  -- SPECIALIST: 52 new rows (originals remapped to reserved ID range).

  -- DOCTOR_SCHEDULE: 1,474 new rows (originals remapped to reserved ID range).

  -- MEDICATION: 100 new rows (originals remapped to reserved ID range).

  -- APPOINTMENT: 2,500 new rows (originals remapped to reserved ID range).

  -- CONSULTATION_SESSION: 1,500 new rows (originals remapped to reserved ID range).

  -- MEDICAL_HISTORY: 1,000 new rows (originals remapped to reserved ID range).

  -- PRESCRIPTION: 800 new rows (originals remapped to reserved ID range).

  -- PRESCRIPTION_ITEM: 1,500 new rows (originals remapped to reserved ID range).

  -- Automated postchecks: all must be zero violations, else rollback.
  SELECT COUNT(*) INTO conflict_count
  FROM APPOINTMENT a JOIN DOCTOR_SCHEDULE ds ON ds.ScheduleID=a.ScheduleID
  WHERE a.AppointmentID BETWEEN 6000000 AND 6099999
    AND (ds.DoctorID<>a.DoctorID OR ds.ScheduleDate<>DATE(a.AppointmentDateTime)
      OR ds.AvailabilityStatus<>'Available'
      OR a.AppointmentDateTime<TIMESTAMP(ds.ScheduleDate,ds.StartTime)
      OR DATE_ADD(a.AppointmentDateTime, INTERVAL a.EstimatedDuration MINUTE)>TIMESTAMP(ds.ScheduleDate,ds.EndTime));
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: BR25/BR50/BR51 violation'; END IF;

  SELECT COUNT(*) INTO conflict_count
  FROM APPOINTMENT a JOIN APPOINTMENT b ON a.DoctorID=b.DoctorID AND a.AppointmentID<b.AppointmentID
  WHERE a.AppointmentID BETWEEN 6000000 AND 6099999
    AND b.AppointmentID BETWEEN 6000000 AND 6099999
    AND a.Status NOT IN ('Cancelled','No-show') AND b.Status NOT IN ('Cancelled','No-show')
    AND a.AppointmentDateTime<DATE_ADD(b.AppointmentDateTime,INTERVAL b.EstimatedDuration MINUTE)
    AND b.AppointmentDateTime<DATE_ADD(a.AppointmentDateTime,INTERVAL a.EstimatedDuration MINUTE);
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: BR34 overlap violation'; END IF;

  SELECT COUNT(*) INTO conflict_count
  FROM DOCTOR d LEFT JOIN GENERAL_PRACTITIONED gp ON gp.DoctorID=d.DoctorID
    LEFT JOIN SPECIALIST sp ON sp.DoctorID=d.DoctorID
  WHERE d.DoctorID BETWEEN 6000000 AND 6099999
    AND ((gp.DoctorID IS NULL AND sp.DoctorID IS NULL)
      OR (gp.DoctorID IS NOT NULL AND sp.DoctorID IS NOT NULL));
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: specialization violation'; END IF;

  SELECT COUNT(*) INTO conflict_count FROM MEDICAL_HISTORY mh
    JOIN CONSULTATION_SESSION cs ON cs.SessionID=mh.SessionID
    JOIN APPOINTMENT a ON a.AppointmentID=cs.AppointmentID
  WHERE mh.MedicalHistoryID BETWEEN 6000000 AND 6099999
    AND (a.Patient<>mh.Patient OR a.Status<>'Completed');
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: medical history mismatch'; END IF;

  SELECT COUNT(*) INTO conflict_count FROM PRESCRIPTION p
    JOIN CONSULTATION_SESSION cs ON cs.SessionID=p.SessionID
    JOIN APPOINTMENT a ON a.AppointmentID=cs.AppointmentID
  WHERE p.PrescriptionID BETWEEN 6000000 AND 6099999
    AND (a.Patient<>p.Patient OR a.DoctorID<>p.DoctorID OR a.Status<>'Completed');
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: prescription mismatch'; END IF;

  SELECT COUNT(*) INTO conflict_count FROM CONSULTATION_SESSION cs
    JOIN APPOINTMENT a ON a.AppointmentID=cs.AppointmentID
  WHERE cs.SessionID BETWEEN 6000000 AND 6099999
    AND (a.Status<>'Completed'
      OR (a.Modality='Telemedicine' AND cs.SessionType<>'Virtual')
      OR (a.Modality='In-person' AND cs.SessionType<>'In-person'));
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: session type mismatch'; END IF;

  SELECT COUNT(*) INTO conflict_count FROM PRESCRIPTION p
    LEFT JOIN PRESCRIPTION_ITEM pi ON pi.PrescriptionID=p.PrescriptionID
  WHERE p.PrescriptionID BETWEEN 6000000 AND 6099999 AND pi.PrescriptionID IS NULL;
  IF conflict_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: prescription without item'; END IF;

  SELECT COUNT(*) INTO conflict_count FROM `vw_appointmentdetails`
  WHERE AppointmentID BETWEEN 6000000 AND 6099999;
  IF conflict_count<>2500 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: Appointment View count mismatch'; END IF;

  SELECT COUNT(*) INTO conflict_count FROM `vw_prescriptiondetails`
  WHERE PrescriptionID BETWEEN 6000000 AND 6099999;
  IF conflict_count<>1500 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: Prescription View count mismatch'; END IF;

  SELECT ((SELECT COUNT(*) FROM `USER_ACCOUNT` WHERE `UserID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `SPECIALTY` WHERE `SpecialtyID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `DOCTOR` WHERE `DoctorID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `PATIENT` WHERE `Patient` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `GENERAL_PRACTITIONED` WHERE `DoctorID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `SPECIALIST` WHERE `DoctorID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `DOCTOR_SCHEDULE` WHERE `ScheduleID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `MEDICATION` WHERE `MedicationID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `APPOINTMENT` WHERE `AppointmentID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `CONSULTATION_SESSION` WHERE `SessionID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `MEDICAL_HISTORY` WHERE `MedicalHistoryID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `PRESCRIPTION` WHERE `PrescriptionID` BETWEEN 6000000 AND 6099999) +
          (SELECT COUNT(*) FROM `PRESCRIPTION_ITEM` WHERE `PrescriptionItemID` BETWEEN 6000000 AND 6099999) ) INTO inserted_count;
  IF inserted_count < 11000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MC26: fewer than 11,000 inserted rows'; END IF;
  COMMIT;
  SELECT inserted_count AS NewRowsImported, 'PASS' AS Result;
END$$
DELIMITER ;
CALL `mc26_import_once`();
DROP PROCEDURE IF EXISTS `mc26_import_once`;
